/* Local Gmail-style mailboxes. Messages and access links follow booking state. */
'use strict';
const mailboxBase={render,handle,bar:demoBar};
function mailboxRecipient(){return state.ui.mailRecipient||'organizer';}
function mailboxPeople(){return [{id:'organizer',name:name(state.request||defaults),email:state.request?.email||defaults.email,role:'Organizer'},{id:'priya',name:'Priya Nair',email:'priya@horizon.example',role:'Guest'},...(state.pickup?pickup().reservations.filter(r=>r.guest.email!=='priya@horizon.example').map(r=>({id:r.id,name:v2Full(r.guest),email:r.guest.email,role:'Guest'})):[]),...(state.pickup?roomSlots().filter(s=>s.guest&&s.payer==='Organizer'&&s.guest.email.toLowerCase()!==(state.request?.email||defaults.email).toLowerCase()).map(s=>({id:s.id,name:v2Full(s.guest),email:s.guest.email,role:'Guest'})):[]),...(state.pickup?.sharedEmail?[{id:'shared',name:state.pickup.sharedEmail.split('@')[0],email:state.pickup.sharedEmail,role:'Guest'}]:[])];}
function mailboxPerson(){return mailboxPeople().find(p=>p.id===mailboxRecipient())||mailboxPeople()[0];}
function mailboxMessages(){const person=mailboxPerson(),r=state.pickup?.reservations.find(r=>r.guest.email===person.email)|| (state.pickup?organizerPaidGuest(roomSlots().find(s=>s.guest?.email===person.email&&s.payer==='Organizer')):null);if(person.role==='Organizer'){if(!state.quote)return [];const msgs=[{id:'quote',subject:'Your group booking quote · GBR-008',preview:'Review your quote, banquet event order and contract.',heading:'Your group booking is ready to review',body:'We have prepared your quote for '+state.request.group+'. Review the rooms, meeting space, meals and contract through your personal link.',cta:'Review group booking',action:'mail-link-quote'}];if(state.quote.paid)msgs.unshift({id:'deposit',subject:'Deposit received · '+money(totals().deposit),preview:'Thank you. Your group deposit has been received.',heading:'Your deposit has been received',body:'Deposit '+money(totals().deposit)+' received for GBR-008. You can view your contract, invoice and remaining balance through the same organizer link.',cta:'View group booking',action:'mail-link-organizer'});if(state.reservation?.status==='Confirmed')msgs.unshift({id:'confirmed',subject:'Group confirmed · assign your rooms',preview:'Your group is confirmed. Assign guests or share your group code.',heading:'Your group reservation is confirmed',body:'Reservation #00031 is confirmed. Assign guests to your blocked rooms, review your schedule and invite guests who want to book and pay individually.',cta:'Assign your rooms',action:'mail-link-rooms'});return msgs;}
 const msgs=[];if(r){if(r.paid)msgs.push({id:'receipt',subject:'Your room is booked · #'+r.id,preview:r.type+' · '+dates()+' · Paid '+money(r.amount),heading:'Your room is booked',body:'Hi '+r.guest.first+', your '+r.type+' is confirmed for '+dates()+(r.organizerPaid?'. Your room is paid by the organizer.':'. Payment received: '+money(r.amount)+'.')+' Your reservation is #'+r.id+'.',cta:'View my stay',action:'mail-link-guest-'+person.id});else msgs.push({id:'room-invite',subject:'Your room invitation · Horizon Foundation',preview:'Confirm your '+r.type+' and pay '+money(r.amount)+'.',heading:'You are invited to the retreat',body:'Hi '+r.guest.first+', '+name()+' has assigned a '+r.type+' to you in the Horizon Foundation block. Use your personal link to confirm and pay for your room.',cta:'Confirm room & pay',action:'mail-link-payment-'+r.id});if(r.activities.some(a=>a.startsWith('Room changed')))msgs.unshift({id:'room-update',subject:'Your room assignment has been updated · #'+r.id,preview:r.type+' · Room '+r.unit,heading:'Your room has been updated',body:'Your room is now '+r.type+' · '+r.unit+'. Your stay dates and paid amount are unchanged.',cta:'View updated stay',action:'mail-link-guest-'+r.id});if(r.extrasPaid)msgs.unshift({id:'extras',subject:'Extras payment received · #'+r.id,preview:'Payment received: '+money(r.extrasPaid),heading:'Your extras are confirmed',body:'We received your demo payment of '+money(r.extrasPaid)+' for the activities and extras on your stay.',cta:'View my charges',action:'mail-link-charges-'+person.id});}
 if(!r&&state.reservation?.status==='Confirmed')msgs.push({id:'code',subject:'Join the Horizon Foundation retreat · GBR-008',preview:'Choose your room at the group rate and book your stay.',heading:'Join us at Cedar Valley',body:'Hi '+person.name.split(' ')[0]+', you are invited to the Horizon Foundation Annual Leadership Retreat, '+dates()+'. Use this personal link to choose a room from the group block. Your group code is GBR-008.',cta:'Choose my room',action:'mail-link-code'});return msgs;}
function mailboxPage(){const person=mailboxPerson(),messages=mailboxMessages(),selected=messages.find(m=>m.id===state.ui.mailMessage);const logo='<div class="gmail-brand"><span>Email</span></div>';const switcher='<div class="mailbox-identity"><span>Demo mailbox</span><select name="mailbox-recipient" aria-label="Demo email recipient">'+mailboxPeople().map(p=>'<option value="'+p.id+'" '+(p.id===person.id?'selected':'')+'>'+p.name+' · '+p.role+'</option>').join('')+'</select><small>'+esc(person.email)+'</small></div>';
 const sidebar='<aside class="gmail-sidebar"><button class="gmail-compose" data-action="mail-compose">Compose</button><button class="active" data-action="mail-inbox">Inbox <b>'+messages.length+'</b></button><button data-action="mail-starred">Starred</button><button data-action="mail-sent">Sent</button><button data-action="mail-drafts">Drafts</button><div class="gmail-labels">Labels<br><span>Retreat booking</span></div></aside>';
 let content;if(selected){content='<div class="gmail-message-tools">'+button('← Back to inbox','mail-inbox','link')+'</div><article class="gmail-message"><h1>'+selected.subject+'</h1><div class="gmail-sender"><span class="gmail-avatar">C</span><div><b>Cedar Valley Retreat & Conference Center</b> <small>&lt;bookings@cedarvalley.example&gt;</small><p>to '+esc(person.name)+' &lt;'+esc(person.email)+'&gt;</p></div><small>Sep 22, 2026</small></div><div class="gmail-email-card"><div class="gmail-venue">CEDAR VALLEY</div><h2>'+selected.heading+'</h2><p>'+esc(selected.body)+'</p><div class="gmail-booking-facts">'+detail('Group',esc(state.request.group))+detail('Dates',dates()+' · '+nights()+' nights')+detail('Group code','GBR-008')+'</div><button class="mail-secure-link" data-action="'+selected.action+'">'+selected.cta+'</button><p class="gmail-private-link">This personal link is for '+esc(person.email)+'.</p><p>We look forward to welcoming you,<br>The Cedar Valley team</p></div></article>';}else{content='<div class="gmail-list-tools"><span>Inbox</span><small>'+ (messages.length?'1–'+messages.length+' of '+messages.length:'0 messages')+'</small></div><div class="gmail-mail-list">'+messages.map(m=>'<button class="gmail-mail-row" data-action="mail-open-'+m.id+'"><span class="gmail-star">☆</span><b>Cedar Valley</b><span><strong>'+m.subject+'</strong><small> — '+m.preview+'</small></span><time>Sep 22</time></button>').join('')+(!messages.length?'<div class="gmail-empty">Your inbox is empty. A booking email will appear after the venue sends your quote or invitation.</div>':'')+'</div>';}
 return '<div class="gmail-demo"><header class="gmail-top">'+logo+'<input name="mailbox-search" placeholder="Search mail" aria-label="Search mail">'+switcher+'<span class="gmail-user">'+esc(person.name.charAt(0))+'</span></header><div class="gmail-layout">'+sidebar+'<main class="gmail-content">'+content+'</main></div></div>';}
function openMailbox(recipient){if(recipient)state.ui.mailRecipient=recipient;state.ui.mailMessage=null;modal=null;navigate('guest','mailbox');}
render=function(){if(state.ui.app==='guest'&&['mailbox','email','guest-inbox'].includes(state.ui.guest)){$('#demo').innerHTML=demoBar();$('#app').innerHTML=mailboxPage();renderOverlay();return;}mailboxBase.render();};
demoBar=function(){let html=mailboxBase.bar();if(state.quote&&!v2Active())html=html.replace('<div class="demo-tools">','<div class="demo-tools"><button data-action="mail-organizer">Organizer email</button>');if(v2Active())html=html.replace('data-action="v2-organizer"','data-action="mail-organizer"').replace('>Organizer link</button>','>Organizer email</button>').replace('data-action="v2-code"','data-action="mail-guest"').replace('>Guest link</button>','>Guest email</button>').replace('data-action="v2-inbox"','data-action="mail-inbox"').replace('>Demo inbox</button>','>Demo inbox</button>');return html;};
handle=function(a,el){try{
 if(a==='mail-organizer'){openMailbox('organizer');return;}
 if(a==='mail-guest'){openMailbox('priya');return;}
 if(a==='mail-inbox'||a==='v2-inbox'){openMailbox();return;}
 if(a==='open-email'){openMailbox('organizer');return;}
 if(a.startsWith('mail-open-')){state.ui.mailMessage=a.slice(10);save();render();return;}
 if(a==='v2-sample'||a==='v2-current'){mailboxBase.handle(a,el);if(v2Active())openMailbox('organizer');return;}
 if(a==='send-quote'){state.ui.mailRecipient='organizer';state.ui.mailMessage=null;return mailboxBase.handle(a,el);}
 if(a==='mail-link-quote'){if(state.quote?.status!=='Sent')return openOrganizerPortal();state.ui.portalRole='organizer';state.ui.portalPage='documents';return mailboxBase.handle('review-quote');}
 if(a==='mail-link-rooms'){requireState(state.reservation?.status==='Confirmed','The group reservation is not confirmed yet.');if(!state.pickup)setupPickup(false);pickup().active=true;return openOrganizerPortal('rooms');}
 if(a==='mail-link-organizer'){return openOrganizerPortal();}
 if(a==='mail-link-code'){state.ui.portalRole='guest';state.ui.portalPage='room';state.ui.portalGuestId=null;pickup().codeApplied=true;pickup().invitedSlot=null;const person=mailboxPerson(),parts=person.name.split(' ');pickup().guestDraft={first:parts[0],last:parts.slice(1).join(' '),email:person.email};modal=null;return navigate('guest','group-code');}
 if(a.startsWith('mail-link-guest-')){const id=a.slice(16);return openGuestPortal('stay',id==='priya'?pickup().reservations.find(r=>r.guest.email==='priya@horizon.example')?.id:id);}
 if(a.startsWith('mail-link-payment-')){return openGuestPortal('payment',a.slice(18));}
 if(a.startsWith('mail-link-charges-')){const id=a.slice(18);return openGuestPortal('charges',id==='priya'?pickup().reservations.find(r=>r.guest.email==='priya@horizon.example')?.id:id);}
 if(['mail-compose','mail-starred','mail-sent','mail-drafts'].includes(a)){return;}
 if(a==='v2-send-code'){mailboxBase.handle(a,el);if(!modal){state.ui.mailRecipient='shared';}return;}
 return mailboxBase.handle(a,el);
 }catch(e){toast(e.message,true);}};
document.addEventListener('change',e=>{if(e.target.name==='mailbox-recipient'){state.ui.mailRecipient=e.target.value;state.ui.mailMessage=null;save();render();}});
document.addEventListener('input',e=>{if(e.target.name==='mailbox-search'){const text=e.target.value.toLowerCase();document.querySelectorAll('.gmail-mail-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(text));}});
render();
